        n = len(bars)
        colors = {r % n: col for r, col in bars}
        return [[colors[r % n]] * w for r in range(h)]

    # Track runs on anti-diagonals (demo 3's orientation), indexed by r+c.
    # A period equal to the number of distinct marked tracks reproduces the
    # demonstrated diagonal tiling; test the other orientation as fallback.
    for sign in (1, -1):
        tracks = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = r + c if sign == 1 else c - r
                    tracks.setdefault(k, []).append(v)
        tracks = {k: vals[0] for k, vals in tracks.items()
                  if len(vals) >= 2 and len(set(vals)) == 1}
        if len(tracks) >= 2:
            n = len(tracks)
            palette = {k % n: col for k, col in tracks.items()}
            if len(palette) == n:
                return [[palette[((r+c) if sign == 1 else (c-r)) % n]
                         for c in range(w)] for r in range(h)]
